/// Base de Données Officielle des Voies PADA (Projet d'Adressage du District d'Abidjan)
/// Ministère de la Construction, du Logement et de l'Urbanisme (MCLU) / BNETD / IGN FI / GEOFIT
library;

enum PadaWayType { boulevard, avenue, rue, impasse, ruelle, rondPoint }

class PadaWay {
  final String id;
  final PadaWayType type;
  final String nom;
  final String? ancienNom;
  final String commune;
  final String? quartier;
  final int? longueurM;
  final String? codePada;

  const PadaWay({
    required this.id,
    required this.type,
    required this.nom,
    this.ancienNom,
    required this.commune,
    this.quartier,
    this.longueurM,
    this.codePada,
  });

  factory PadaWay.fromJson(Map<String, dynamic> json) {
    PadaWayType parseType(String? t) {
      final s = (t ?? '').toUpperCase();
      if (s.contains('BOULEVARD')) return PadaWayType.boulevard;
      if (s.contains('AVENUE')) return PadaWayType.avenue;
      if (s.contains('IMPASSE')) return PadaWayType.impasse;
      if (s.contains('RUELLE')) return PadaWayType.ruelle;
      if (s.contains('ROND-POINT') || s.contains('ROND POINT')) return PadaWayType.rondPoint;
      return PadaWayType.rue;
    }

    return PadaWay(
      id: json['id'] ?? '',
      codePada: json['codePada'] ?? json['id'],
      type: parseType(json['type']),
      nom: json['nom'] ?? '',
      ancienNom: json['ancienNom'],
      commune: json['commune'] ?? '',
      quartier: json['quartier'],
      longueurM: json['longueurM'],
    );
  }

  String get typeLabel {
    switch (type) {
      case PadaWayType.boulevard:
        return 'BOULEVARD';
      case PadaWayType.avenue:
        return 'AVENUE';
      case PadaWayType.rue:
        return 'RUE';
      case PadaWayType.impasse:
        return 'IMPASSE';
      case PadaWayType.ruelle:
        return 'RUELLE';
      case PadaWayType.rondPoint:
        return 'ROND-POINT';
    }
  }
}

