// 3. FONCTIONS DE RECHERCHE ET FILTRAGE
// ══════════════════════════════════════════════════════════════════════════════

String _normalize(String text) {
  return text
      .toLowerCase()
      .replaceAll(RegExp(r'[àáâãäå]'), 'a')
      .replaceAll(RegExp(r'[èéêë]'), 'e')
      .replaceAll(RegExp(r'[ìíîï]'), 'i')
      .replaceAll(RegExp(r'[òóôõö]'), 'o')
      .replaceAll(RegExp(r'[ùúûü]'), 'u')
      .replaceAll(RegExp(r'[ç]'), 'c')
      .replaceAll(RegExp(r'[^a-z0-9]'), '');
}

class PadaDoorNumber {
  final String idNumero;
  final int numero;
  final String idVoie;
  final String voie;
  final String codePostal;
  final String commune;
  final String district;
  final String pays;
  final String adresseComplete;

  const PadaDoorNumber({
    required this.idNumero,
    required this.numero,
    required this.idVoie,
    required this.voie,
    required this.codePostal,
    required this.commune,
    required this.district,
    required this.pays,
    required this.adresseComplete,
  });
}

class ScoredPadaWay {
  final PadaWay way;
  final int score;
  final bool isLengthCompatible;
  final String probabilityLabel;
  final String formattedSuggestion;
  final bool isExactDoor;
  final String? exactDoorId;
  final int? closestDoorNumber;
  final int? doorDelta;
  final String? nearestDoorInfo;
  final String? cadastralAddress;

  const ScoredPadaWay({
    required this.way,
    required this.score,
    required this.isLengthCompatible,
    required this.probabilityLabel,
    required this.formattedSuggestion,
    this.isExactDoor = false,
    this.exactDoorId,
    this.closestDoorNumber,
    this.doorDelta,
    this.nearestDoorInfo,
    this.cadastralAddress,
  });
}

List<ScoredPadaWay> searchPadaWaysScored(String query, {String? commune, String? quartier}) {
  final trimmed = query.trim();
  final numberMatch = RegExp(r'\d+').firstMatch(trimmed);
  final extractedNumber = numberMatch != null ? int.tryParse(numberMatch.group(0)!) : null;
  final textQuery = _normalize(trimmed.replaceAll(RegExp(r'\d+'), '').trim());
  final allWays = [...PADA_BOULEVARDS, ...PADA_AVENUES, ...PADA_RUES];

  final List<ScoredPadaWay> results = [];

  for (final way in allWays) {
    int score = 0;
    bool isExactDoor = false;
    String? exactDoorId;
    int? closestDoorNumber;
    int? doorDelta;
    String? nearestDoorInfo;
    String? cadastralAddress;

    // 1. Filtrage par commune
    if (commune != null && commune.isNotEmpty) {
      final normWayCommune = _normalize(way.commune);
      final normTargetCommune = _normalize(commune);
      if (!normWayCommune.contains(normTargetCommune) && way.type != PadaWayType.boulevard) {
        continue;
      }
    }

    // 2. Score de quartier
    bool isQuartierMatch = false;
    if (quartier != null && quartier.isNotEmpty && way.quartier != null) {
      final normWayQuartier = _normalize(way.quartier!);
      final normTargetQuartier = _normalize(quartier);
      if (normWayQuartier.contains(normTargetQuartier) || normTargetQuartier.contains(normWayQuartier)) {
        isQuartierMatch = true;
        score += 40;
      }
    } else if (way.type == PadaWayType.boulevard) {
      score += 20;
    }

    // 3. Probabilité par Métrage (longueurM)
    bool isLengthCompatible = true;
    if (extractedNumber != null && way.longueurM != null) {
      final maxAllowedNumber = (way.longueurM! * 1.2).round();
      if (extractedNumber > maxAllowedNumber) {
        isLengthCompatible = false;
        score -= 50;
      } else {
        isLengthCompatible = true;
        score += 30;
      }
    } else if (extractedNumber != null && way.type == PadaWayType.boulevard) {
      isLengthCompatible = true;
      score += 20;
    }

    // 4. Recherche textuelle
    if (textQuery.isNotEmpty) {
      final normNom = _normalize(way.nom);
      final normAncien = way.ancienNom != null ? _normalize(way.ancienNom!) : '';

      if (normNom.contains(textQuery)) {
        score += 50;
      } else if (normAncien.isNotEmpty && normAncien.contains(textQuery)) {
        score += 40;
      } else {
        score -= 20;
      }
    } else {
      if (isQuartierMatch) score += 20;
    }

    final finalScore = score.clamp(5, 100);

    String probabilityLabel = 'Faible';
    if (!isLengthCompatible) {
      probabilityLabel = 'Incompatible';
    } else if (isExactDoor || finalScore >= 70) {
      probabilityLabel = 'Haute';
    } else if (finalScore >= 40) {
      probabilityLabel = 'Moyenne';
    }

    String formattedSuggestion = way.nom;
    if (extractedNumber != null) {
      formattedSuggestion = '$extractedNumber, ${way.nom}';
    }

    results.add(ScoredPadaWay(
      way: way,
      score: finalScore,
      isLengthCompatible: isLengthCompatible,
      probabilityLabel: probabilityLabel,
      formattedSuggestion: formattedSuggestion,
      isExactDoor: isExactDoor,
      exactDoorId: exactDoorId,
      closestDoorNumber: closestDoorNumber,
      doorDelta: doorDelta,
      nearestDoorInfo: nearestDoorInfo,
      cadastralAddress: cadastralAddress,
    ));
  }

  results.sort((a, b) => b.score.compareTo(a.score));
  return results;
}

List<PadaWay> searchPadaWays(String query, {String? commune, String? quartier}) {
  return searchPadaWaysScored(query, commune: commune, quartier: quartier).map((r) => r.way).toList();
}

List<PadaWay> getWaysForQuartier(String commune, String quartier) {
  final normQuartier = _normalize(quartier);
  final normCommune = _normalize(commune);

  final avenues = PADA_AVENUES.where((w) {
    final wCommune = _normalize(w.commune);
    final wQuartier = w.quartier != null ? _normalize(w.quartier!) : '';
    final communeMatch = wCommune.contains(normCommune);
    final quartierMatch = wQuartier.isNotEmpty
        ? (wQuartier.contains(normQuartier) || normQuartier.contains(wQuartier))
        : true;
    return communeMatch && quartierMatch;
  }).toList();

  final boulevards = PADA_BOULEVARDS.where((b) => _normalize(b.commune).contains(normCommune)).toList();

  return [...boulevards, ...avenues];
}
